/**************TEST CLASS DECLARATION*************/
 class TogglzConsoleServletTest {}
/**************TEST SETUP BEGIN*************/
@BeforeEach
void setUp() throws IOException{
        featureManager = new TestFeatureManager(TestFeature.class);
        featureManager.enable(TestFeature.FEATURE_A);

        servlet = new TestableConsoleServlet();
        servlet.initForTesting(featureManager, false, false);

        request = mock(HttpServletRequest.class);
        response = mock(HttpServletResponse.class);
        servletContext = mock(ServletContext.class);

        servlet.servletContext = servletContext;

        responseBody = new ByteArrayOutputStream();
        ServletOutputStream sos = new ServletOutputStream() {
            @Override public boolean isReady() { return true; }
            @Override public void setWriteListener(WriteListener l) {}
            @Override public void write(int b) { responseBody.write(b); }
            @Override public void write(byte[] b, int off, int len) { responseBody.write(b, off, len); }
        };
        lenient().when(response.getOutputStream()).thenReturn(sos);
        lenient().when(servletContext.getServerInfo()).thenReturn("TestServer");
        lenient().when(servletContext.getServletContextName()).thenReturn(null);
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
void rootPath_dispatchesToRedirectHandler() throws Exception{
        stubRequestUri(request, "/togglz", "/");

        servlet.service(request, response);

        verify(response).sendRedirect(contains("index"));
    }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private static void stubRequestUri(HttpServletRequest req, String servletPath, String pathInfo){
        String uri = servletPath + pathInfo;
        lenient().when(req.getContextPath()).thenReturn("");
        lenient().when(req.getServletPath()).thenReturn(servletPath);
        lenient().when(req.getRequestURI()).thenReturn(uri);
        lenient().when(req.getMethod()).thenReturn("GET");
    }
/**************TEST HELPER METHOD END*************/


