private HttpServletResponse buildResponseMock(ByteArrayOutputStream bos) throws Exception{
        HttpServletResponse response = mock(HttpServletResponse.class);
        ServletOutputStream sos = new ServletOutputStream() {
            @Override public boolean isReady() { return true; }
            @Override public void setWriteListener(WriteListener l) {}
            @Override public void write(int b) { bos.write(b); }
            @Override public void write(byte[] b, int off, int len) { bos.write(b, off, len); }
        };
        when(response.getOutputStream()).thenReturn(sos);
        return response;
    }
private void processRequest(String servletPath, String pathInfo, HttpServletResponse response) throws Exception{
        HttpServletRequest request = mock(HttpServletRequest.class);
        FeatureManager featureManager = mock(FeatureManager.class);
        ServletContext servletContext = mock(ServletContext.class);

        String uri = servletPath + pathInfo;
        when(request.getContextPath()).thenReturn("");
        when(request.getServletPath()).thenReturn(servletPath);
        when(request.getRequestURI()).thenReturn(uri);

        RequestEvent event = new RequestEvent(featureManager, servletContext,
                request, response, new RequestContext(false));

        handler.process(event);
    }
